mkdir -p /root/output && cp /root/data/workbook.xlsx /root/output/result.xlsx && python - <<'PY'
from openpyxl import load_workbook
from pathlib import Path
path=Path('/root/output/result.xlsx')
wb=load_workbook(path, data_only=False)
print('Workbook sheets:', wb.sheetnames)
for wsname in ['Task','Data']:
    ws=wb[wsname]
    print('\n'+'='*80)
    print(f'Sheet {wsname}: max_row={ws.max_row}, max_col={ws.max_column}')
    if wsname=='Task':
        print('Rows 1-55, columns A-L (values/formulas):')
        for r in range(1,56):
            vals=[]
            for c in range(1,13):
                v=ws.cell(r,c).value
                vals.append('' if v is None else str(v))
            print(f'{r:02d}: ' + ' | '.join(vals))
    else:
        # all populated columns rows 1-40
        max_col=0
        for row in ws.iter_rows(min_row=1, max_row=40):
            for cell in row:
                if cell.value is not None:
                    max_col=max(max_col, cell.column)
        print(f'Rows 1-40, columns A-{ws.cell(1,max_col).column_letter} (populated through {max_col}):')
        for r in range(1,41):
            vals=[]
            for c in range(1,max_col+1):
                v=ws.cell(r,c).value
                vals.append('' if v is None else str(v))
            print(f'{r:02d}: ' + ' | '.join(vals))
